def _max_bound(a, b):
    if a is None:
        return b
    if b is None:
        return a
    return max(a, b)


def _min_bound(a, b):
    if a is None:
        return b
    if b is None:
        return a
    return min(a, b)


def _active_dependencies(row, features):
    for dep in row.get('deps', []):
        if isinstance(dep, dict):
            feature = dep.get('feature')
            if feature and feature not in features:
                continue
            yield dep
        else:
            yield dep


def _is_acyclic(selected, features):
    graph = {}
    for name, row in selected.items():
        graph[name] = [
            dep['name'] if isinstance(dep, dict) else dep
            for dep in _active_dependencies(row, features)
        ]

    visiting = set()
    visited = set()

    def visit(name):
        if name in visiting:
            return False
        if name in visited:
            return True
        visiting.add(name)
        for dependency in graph.get(name, []):
            if not visit(dependency):
                return False
        visiting.remove(name)
        visited.add(name)
        return True

    return all(visit(name) for name in graph)


def solve(data):
    packages = data['packages']
    names = sorted(packages)
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    best = None
    best_vector = None

    constraints = {
        name: (bounds[0], bounds[1])
        for name, bounds in data['roots'].items()
    }

    def search(selected, required):
        nonlocal best, best_vector

        for name, row in selected.items():
            low, high = required[name]
            version = row['version']
            if low is not None and version < low:
                return
            if high is not None and version > high:
                return

        pending = sorted(set(required) - set(selected))
        if not pending:
            if not _is_acyclic(selected, features):
                return
            vector = tuple(
                selected[name]['version'] if name in selected else -1
                for name in names
            )
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {name: row['version'] for name, row in selected.items()}
            return

        name = pending[0]
        for row in choose(
            packages.get(name, []),
            required[name],
            blocked.get(name, []),
            pins.get(name),
        ):
            next_selected = dict(selected)
            next_selected[name] = row
            next_required = dict(required)

            for dep in _active_dependencies(row, features):
                if isinstance(dep, dict):
                    dep_name = dep['name']
                    dep_low = dep.get('min')
                    dep_high = dep.get('max')
                else:
                    dep_name = dep
                    dep_low = dep_high = None

                old_low, old_high = next_required.get(dep_name, (None, None))
                next_required[dep_name] = (
                    _max_bound(old_low, dep_low),
                    _min_bound(old_high, dep_high),
                )

            search(next_selected, next_required)

    search({}, constraints)
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}
